        WHERE proc.oid = 'storage.delete_lifecycle_objects(uuid[])'::regprocedure
          AND acl.grantee NOT IN (0, proc.proowner)
    LOOP
        EXECUTE format('REVOKE ALL ON FUNCTION storage.delete_lifecycle_objects(uuid[]) FROM %s', role_name);
